export const DIGISTYLE_PRODUCTS_BY_ID: Record<number, DigistyleCatalogProduct> =
  Object.fromEntries(
    DIGISTYLE_PRODUCTS.filter((p) => p.digistyleId != null).map((p) => [
      p.digistyleId!,
      p,
    ])
  )

export function digistyleProductsByIds(ids: number[]): DigistyleCatalogProduct[] {
  return ids
    .map((id) => DIGISTYLE_PRODUCTS_BY_ID[id])
    .filter((p): p is DigistyleCatalogProduct => Boolean(p))
}
